# locate the refs array
start = src.index("const refs = [\n") + len("const refs = [\n")
end = src.index("\n];\nrefs.forEach")
body = src[start:end]
lines = body.split("\n")
entries = [l for l in lines if l.strip()]
def key(e):
    s = e.strip().strip('",')
    s = s.replace("&", "").replace("Jr.,", "")
    return re.sub(r"[^a-z0-9 ]", "", s.lower())
for nr in new_refs:
    line = '"' + nr + '",'
    k = key(line)
    pos = len(entries)
    for i, e in enumerate(entries):
        if key(e) > k:
            pos = i; break
    entries.insert(pos, line)
src = src[:start] + "\n".join(entries) + src[end:]

